```go
// snapshotDuplicateFields rejects snapshots that declare a semantic field more
// than once in the same object. encoding/json's struct unmarshal silently keeps
// the LAST occurrence of a duplicated key, which lets a document carry two
// formatVersion/contentId/graph values (or two name/upstreams values per
// dataset record) while only one is validated. Field names are compared after
// JSON string unescaping (so "na\u006de" is "name") and case-folding (so
// "Name" is the same field as "name"); dataset names themselves are untouched.
// Extra, unknown fields keep their existing ignore behavior and are not
// checked.
func snapshotDuplicateFields(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil {
		return nil // let the regular unmarshal report the malformed JSON
	}
	d, ok := tok.(json.Delim)
	if !ok || d != '{' {
		return nil
	}
	seen := map[string]bool{}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil
		}
		folded := strings.ToLower(key)
		if canonical, known := snapshotTopFields[folded]; known {
			if seen[folded] {
				return fmt.Errorf("%w: duplicate JSON field %q at the top level of the snapshot", ErrInvalidArgument, canonical)
			}
			seen[folded] = true
			if folded == "graph" {
				if err := scanGraphObject(dec); err != nil {
					return err
				}
				continue
			}
		}
		if err := skipJSONValue(dec); err != nil {
			return nil
		}
	}
	if _, err := dec.Token(); err != nil {
		return nil
	}
	return nil
}
```

