func skipMatching(dec *json.Decoder, open, close json.Delim) error {
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		if d, ok := tok.(json.Delim); ok {
			switch d {
			case open:
				depth++
			case close:
				depth--
			}
		}
	}
	return nil
}
```

